`,(0,r.jsx)(c,{title:"The Description ↔ Discernment loop",intro:"Fluent AI use happens in a tight loop: you describe what you want, the model responds, you discern what's useful, and you describe again — sharper this time. Delegation sets the stage; diligence closes it.",cards:[{title:"Delegation",description:"Decide what's worth handing to AI in the first place."},{title:"Diligence",description:"Verify, attribute, and own the final product."},{title:"Description",description:"Communicate the vision so the model can act on it.",emphasis:!0},{title:"Discernment",description:"Judge what came back — and feed that judgment forward.",emphasis:!0}],left:{title:"Tell it what good looks like.",description:"Clear, specific, well-structured prompting that translates a creative vision into terms the model can act on."},right:{title:"Judge what came back.",description:"Critical evaluation of the output — quality, relevance, bias — and of the collaboration itself, so the next prompt is sharper."},hubTop:"Prompt",hubBottom:"Refine"}),`
